import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    weights = list(map(int, input[2:]))

    if max(weights) > k:
        print(-1)
        print(0)
        return

    dp = defaultdict(lambda: float('inf'))
    ways = defaultdict(int)
    dp[0] = 0
    ways[0] = 1

    for mask in range(1, 1 << n):
        subset_weight = 0
        count = 0
        for i in range(n):
            if mask & (1 << i):
                subset_weight += weights[i]
                count += 1
        if subset_weight <= k:
            for prev_mask in range(mask):
                if (mask & prev_mask) == prev_mask:
                    new_rides = dp[prev_mask] + (1 if count > 0 else 0)
                    if new_rides < dp[mask]:
                        dp[mask] = new_rides
                        ways[mask] = ways[prev_mask]
                    elif new_rides == dp[mask]:
                        ways[mask] = (ways[mask] + ways[prev_mask]) % 1000000007

    full_mask = (1 << n) - 1
    if dp[full_mask] == float('inf'):
        print(-1)
        print(0)
    else:
        print(dp[full_mask])
        print(ways[full_mask])

if __name__ == "__main__":
    main()
